import re, os, shutil

store = "すさび湯 河原町三条店"
old = "src/Root.tsx"
if os.path.exists(old):
    t = open(old, encoding="utf-8").read()
    m = re.search(r'storeName:\s*"((?:[^"\\]|\\.)*)"', t)
    if m and m.group(1).strip():
        store = m.group(1)

for f in ("src/SimpleStory.tsx", "src/Root.tsx"):
    if os.path.exists(f) and not os.path.exists(f + ".simplebak"):
        shutil.copy(f, f + ".simplebak")

open("src/SimpleStory.tsx", "w", encoding="utf-8").write('import { AbsoluteFill, Img, staticFile } from "remotion";\nimport { loadFont } from "@remotion/google-fonts/YujiSyuku";\nimport { simplePhoto, simplePhrase, simpleHasLogo } from "./simpleData";\n\nconst { fontFamily: brush } = loadFont();\n\nconst BG = "#140b07";\nconst GOLD = "#d4a574";\nconst M = 96;\n\nexport const SimpleStory: React.FC<{ storeName?: string; handle?: string }> = ({\n  storeName = "",\n  handle = "@susabiyu_sanjyo",\n}) => {\n  const src = staticFile(simplePhoto);\n  return (\n    <AbsoluteFill style={{ backgroundColor: BG }}>\n      <AbsoluteFill>\n        <Img\n          src={src}\n          style={{\n            width: "100%",\n            height: "100%",\n            objectFit: "cover",\n            filter: "blur(34px) brightness(0.3)",\n            transform: "scale(1.3)",\n          }}\n        />\n      </AbsoluteFill>\n      <AbsoluteFill\n        style={{\n          background:\n            "linear-gradient(180deg, rgba(20,11,7,0.5) 0%, rgba(20,11,7,0.1) 22%, rgba(20,11,7,0.15) 52%, rgba(20,11,7,0.94) 100%)",\n        }}\n      />\n\n      <div\n        style={{\n          position: "absolute",\n          top: 250,\n          width: "100%",\n          display: "flex",\n          flexDirection: "column",\n          alignItems: "center",\n          gap: 10,\n        }}\n      >\n        {simpleHasLogo ? (\n          <Img src={staticFile("logo.png")} style={{ width: 70, height: "auto", objectFit: "contain" }} />\n        ) : null}\n        <div style={{ color: GOLD, fontFamily: brush, fontSize: 32, letterSpacing: 8, textShadow: "0 2px 12px rgba(0,0,0,0.85)" }}>\n          {storeName}\n        </div>\n      </div>\n\n      <AbsoluteFill style={{ justifyContent: "center", alignItems: "center" }}>\n        <div\n          style={{\n            width: 1080 - M * 2,\n            height: 1000,\n            borderRadius: 14,\n            overflow: "hidden",\n            border: "1px solid rgba(212,165,116,0.4)",\n            boxShadow: "0 24px 70px rgba(0,0,0,0.6)",\n          }}\n        >\n          <Img src={src} style={{ width: "100%", height: "100%", objectFit: "cover" }} />\n        </div>\n      </AbsoluteFill>\n\n      <div\n        style={{\n          position: "absolute",\n          bottom: 290,\n          width: "100%",\n          display: "flex",\n          flexDirection: "column",\n          alignItems: "center",\n          padding: "0 70px",\n        }}\n      >\n        <div style={{ width: 60, height: 1, background: `linear-gradient(90deg, transparent, ${GOLD}, transparent)`, marginBottom: 26 }} />\n        <div\n          style={{\n            color: "#fff",\n            fontFamily: brush,\n            fontSize: 58,\n            letterSpacing: 4,\n            textAlign: "center",\n            lineHeight: 1.5,\n            textShadow: "0 2px 22px rgba(0,0,0,0.9), 0 0 40px rgba(212,165,116,0.25)",\n          }}\n        >\n          {simplePhrase}\n        </div>\n      </div>\n\n      <div\n        style={{\n          position: "absolute",\n          bottom: 150,\n          width: "100%",\n          textAlign: "center",\n          color: "rgba(255,255,255,0.8)",\n          fontFamily: brush,\n          fontSize: 26,\n          letterSpacing: 4,\n          textShadow: "0 2px 12px rgba(0,0,0,0.9)",\n        }}\n      >\n        {handle}\n      </div>\n    </AbsoluteFill>\n  );\n};\n')
open("src/Root.tsx", "w", encoding="utf-8").write('import { Composition } from "remotion";\nimport { SushiStory } from "./SushiStory";\nimport { SimpleStory } from "./SimpleStory";\nimport { photos } from "./photoData";\n\nconst FPS = 30;\nconst INTRO = 72;\nconst OUTRO = 72;\nconst SLIDE = 86;\nconst FADE = 16;\n\nexport const RemotionRoot: React.FC = () => {\n  const n = Math.max(photos.length, 1);\n  const dur = INTRO + n * (SLIDE - FADE) + FADE + OUTRO;\n  return (\n    <>\n      <Composition\n        id="SushiStory"\n        component={SushiStory}\n        fps={FPS}\n        width={1080}\n        height={1920}\n        durationInFrames={dur}\n        defaultProps={{ storeName: "__STORE__", handle: "@susabiyu_sanjyo" }}\n      />\n      <Composition\n        id="SimpleStory"\n        component={SimpleStory}\n        fps={FPS}\n        width={1080}\n        height={1920}\n        durationInFrames={1}\n        defaultProps={{ storeName: "__STORE__", handle: "@susabiyu_sanjyo" }}\n      />\n    </>\n  );\n};\n'.replace("__STORE__", store))
print("OK: SimpleStory を追加しました。 store =", store)
